const{test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const root=path.join(__dirname,'..'),html=fs.readFileSync(path.join(root,'index.html'),'utf8'),source=fs.readFileSync(path.join(root,'experience/advanced-studio.js'),'utf8');
const bank=JSON.parse(html.match(/var ADV_BANK=(\{[^\n]+\});/)[1]);
function context(extra={}){const ctx={Adv:{list:()=>Object.values(bank),get:id=>bank[id]},sessionStorage:{getItem:()=>null},localStorage:{getItem:()=>null},...extra};vm.createContext(ctx);vm.runInContext(source,ctx);return ctx;}
test('Every studio field maps to an existing treatment, with honest counts and prerequisites',()=>{const c=context(),ts=c.AdvancedStudio.treatments();assert.equal(ts.length,6);assert.equal(ts.reduce((n,t)=>n+t.derivation.length,0),70);assert.equal(ts.reduce((n,t)=>n+t.problems.length,0),20);for(const t of ts){const f=c.AdvancedStudio.field(t.id);assert.ok(f.name&&f.needs&&f.method);assert.ok(html.includes("'"+t.id+"':"));}assert.equal(c.AdvancedStudio.field('__proto__'),null);assert.equal(c.AdvancedStudio.field('missing'),null);});
test('Entry choice is voluntary and scoped to a tab, including blocked storage',()=>{assert.equal(context().AdvancedStudio.ready(),false);assert.equal(context({sessionStorage:{getItem:()=>{throw Error('blocked');}}}).AdvancedStudio.ready(),false);assert.equal(context({sessionStorage:{getItem:()=> '1'}}).AdvancedStudio.ready(),true);assert.equal(context({sessionStorage:{getItem:()=> 'corrupt'}}).AdvancedStudio.ready(),false);assert.ok(source.includes("dialog.showModal()"));assert.ok(source.includes("addEventListener('cancel'"));assert.ok(source.includes("host.isConnected&&curView==='adv'"));assert.ok(!source.includes('peq_adv_entered'));});
test('Visible preview preserves primary mobile navigation and ordinary learning',()=>{assert.ok(fs.readFileSync(path.join(root,'experience/home.js'),'utf8').includes('class="as-promo" data-go="adv"'));assert.ok(html.includes('data-go="adv"><span class="ic">δ</span> Advanced Studio'));assert.equal((html.match(/<nav class="mtab">([\s\S]*?)<\/nav>/)[1].match(/data-go=/g)||[]).length,5);assert.ok(source.includes('data-go="learn"'));assert.ok(source.includes('Illustrative phase-space motif; not simulation output.'));});
test('Every advanced route disposes of the previous solver and overlay',()=>{assert.match(source,/function view\(host,id\)\{dismiss\(\);Adv\.stop\(\)/);assert.ok(html.includes('AdvancedStudio.dismiss(); Adv.stop();'));assert.ok(source.includes('AppDesign.enhance(host)'));assert.ok(source.includes("aria-expanded"));});
